"""Original method-first Craft/Structure and Expression/Ideas review candidates.

The four authored cases within each family have distinct situations and reasoning
content; seeds select cases, not superficial noun substitutions. The blueprints
name reasoning patterns, not universal solving algorithms. Nothing here confers
editorial approval, publication, or empirical difficulty calibration.
"""
from english_common import make_item

FAMILIES = {
    'words-context': ['rw3-context-precision', 'rw3-context-polysemy', 'rw3-context-restatement'],
    'text-purpose': ['rw3-purpose-main', 'rw3-purpose-function', 'rw3-purpose-organization'],
    'cross-text': ['rw3-cross-qualified-common', 'rw3-cross-disagreement', 'rw3-cross-evidence-response'],
    'synthesis': ['rw3-synthesis-introduce', 'rw3-synthesis-compare', 'rw3-synthesis-exemplify'],
    'transitions': ['rw3-transition-causal', 'rw3-transition-concessive', 'rw3-transition-elaboration'],
}

BLUEPRINTS = {}

def _blueprint(skill, family, method, formula, structure, misconceptions):
    BLUEPRINTS[family] = dict(skill=skill, method=method, formula=formula,
        structure=structure, misconceptions=misconceptions, variants=4)

_blueprint('words-context', 'rw3-context-precision',
    'Predict the missing meaning from two contextual constraints, then test each word in place.',
    'Contextual evidence + required nuance → a precise completion; familiarity alone is insufficient.',
    'A short prose explanation contains one lexical blank constrained by surrounding details.',
    ['opposite meaning', 'topic association without contextual fit', 'excessive certainty'])
_blueprint('words-context', 'rw3-context-polysemy',
    'Identify the local sense of a familiar word rather than its most common dictionary sense.',
    'Local action or description → contextual sense → a substitutable paraphrase.',
    'A word with multiple senses appears in a self-contained passage; options distinguish those senses.',
    ['literal-for-figurative substitution', 'wrong dictionary sense', 'ignored local relation'])
_blueprint('words-context', 'rw3-context-restatement',
    'Use an explicit contrast or explanatory restatement to constrain the missing word.',
    'Contrast/restatement cue + supporting detail → required semantic relation.',
    'A blank is clarified by an opposing idea or a following explanation.',
    ['reversed contrast', 'plausible topic but wrong relation', 'unsupported intensity'])
_blueprint('text-purpose', 'rw3-purpose-main',
    'Separate what the whole text does from a fact it mentions along the way.',
    'Opening concern + development + ending emphasis → whole-text purpose.',
    'A compact argument or literary discussion develops a recognizable communicative aim.',
    ['detail substituted for purpose', 'unsupported authorial aim', 'overbroad claim'])
_blueprint('text-purpose', 'rw3-purpose-function',
    'Locate the quoted portion in its argumentative context and identify its contribution.',
    'Surrounding claim + quoted portion + subsequent use → rhetorical function.',
    'A particular sentence or detail serves a concession, qualification, analogy, or demonstration.',
    ['content paraphrase without function', 'reversal of support', 'unsupported causal role'])
_blueprint('text-purpose', 'rw3-purpose-organization',
    'Track the sequence of rhetorical moves, preserving how later moves relate to earlier ones.',
    'Move 1 → move 2 → move 3, with relations intact, → organizational summary.',
    'Three linked moves form a mini-argument, interpretation, or problem-response account.',
    ['sequence reversal', 'invented dispute', 'confusing example with counterexample'])
_blueprint('cross-text', 'rw3-cross-qualified-common',
    'Find a proposition both authors support without erasing either author’s qualification.',
    'Supported claims in text 1 ∩ supported claims in text 2 → shared limited position.',
    'Two passages differ in emphasis but overlap on a conditional or qualified conclusion.',
    ['agreement made absolute', 'one author’s view attributed to both', 'shared topic mistaken for shared claim'])
_blueprint('cross-text', 'rw3-cross-disagreement',
    'State the same disputed proposition for both texts and compare each author’s position.',
    'Same proposition + opposing evaluations → specific point of disagreement.',
    'Paired passages agree on some background but dispute a criterion, interpretation, or policy.',
    ['background agreement treated as dispute', 'difference in topic mistaken for disagreement', 'unmentioned position'])
_blueprint('cross-text', 'rw3-cross-evidence-response',
    'Apply the second author’s evidence standard or alternative explanation to the first author’s claim.',
    'Claim in text 1 + relevant evidence/standard in text 2 → warranted response with limits.',
    'A second passage supplies evidence that qualifies, challenges, or narrows an earlier inference.',
    ['counterevidence overextended', 'evidence ignored', 'alternative explanation treated as proof'])
_blueprint('synthesis', 'rw3-synthesis-introduce',
    'Choose notes that supply the definition or explanation required by the stated audience and goal.',
    'Audience knowledge + rhetorical goal → relevant factual notes → concise synthesis.',
    'Bulleted research notes support an introduction or explanation, not a comprehensive summary.',
    ['accurate but irrelevant note', 'assumed background knowledge', 'unsupported mechanism'])
_blueprint('synthesis', 'rw3-synthesis-compare',
    'Choose a shared comparison dimension and accurately relate the two subjects on it.',
    'Requested comparison dimension + matched facts about both subjects → targeted comparison.',
    'Notes contain similarities and differences; the stem selects one precise dimension.',
    ['wrong comparison dimension', 'fact reversal', 'unsupported evaluation'])
_blueprint('synthesis', 'rw3-synthesis-exemplify',
    'Connect a specific fact to the requested generalization without claiming more than the notes show.',
    'Stated general point + relevant concrete case → supported illustration.',
    'Notes mix instances and background; a goal requires an example or a bounded generalization.',
    ['isolated detail without connection', 'universal claim from limited cases', 'irrelevant example'])
_blueprint('transitions', 'rw3-transition-causal',
    'Identify whether the next statement is a consequence and distinguish causation from sequence.',
    'Stated reason or constraint → resulting action/outcome → consequence transition.',
    'An explicit condition motivates a later decision or produces a described result.',
    ['chronology substituted for cause', 'example substituted for effect', 'contrast invented'])
_blueprint('transitions', 'rw3-transition-concessive',
    'Compare the first statement’s implication with the next statement’s actual direction.',
    'Expected implication ≠ next statement, or paired differences → contrast/concession transition.',
    'The second statement limits an expectation or presents a directly contrasting case.',
    ['consequence instead of concession', 'parallelism instead of contrast', 'example instead of reversal'])
_blueprint('transitions', 'rw3-transition-elaboration',
    'Distinguish an example, a restatement, and a procedural next step from a change of argument.',
    'General claim → instance; statement → clarification; or completed step → next step.',
    'A prose sequence requires one exact relationship, with no synonymous valid alternatives.',
    ['cause invented', 'opposition invented', 'summary substituted for next step'])


def _c(passage, right, wrong, evidence, steps, topic, stem=None, difficulty='medium'):
    return dict(passage=passage, right=right, wrong=wrong, evidence=evidence,
                steps=steps, topic=topic, stem=stem, difficulty=difficulty)


STEMS = {
    'rw3-context-precision': 'Which choice completes the text with the most logical and precise word or phrase?',
    'rw3-context-restatement': 'Which choice completes the text with the most logical and precise word or phrase?',
    'rw3-purpose-main': 'Which choice best describes the main purpose of the text?',
    'rw3-purpose-organization': 'Which choice best describes the overall structure of the text?',
    'rw3-cross-qualified-common': 'Based on the texts, both authors would most likely agree with which statement?',
    'rw3-cross-disagreement': 'The authors of the two texts would most likely disagree about which point?',
    'rw3-cross-evidence-response': 'How would the author of Text 2 most likely respond to the reasoning in Text 1?',
    'rw3-transition-causal': 'Which choice completes the text with the most logical transition?',
    'rw3-transition-concessive': 'Which choice completes the text with the most logical transition?',
    'rw3-transition-elaboration': 'Which choice completes the text with the most logical transition?',
}

