def make(family, seed):
    item = dict(CASES[family][seed % 4])
    item['stem'] = item['stem'] or STEMS[family]
    return make_item(family=family, seed=seed, blueprint=BLUEPRINTS[family],
                     demands=['interpret local evidence', 'reject a specific competing relation'], **item)
